// Created: 2026-08-19

/**
 * #3569 regression suite: base-ref resolution must prefer `origin/<base>`.
 *
 * Builds REAL throwaway git repos rather than mocking git, matching the #3365
 * suite next door, because the bug lives in which ref git is asked about, not
 * in our parsing of the answer.
 *
 * The shape reproduced here is the normal state of a worktree-heavy checkout:
 * nobody checks `main` out, work lands via squash merge on the remote, so the
 * LOCAL main drifts behind while `origin/main` tracks reality. Measured
 * 2026-08-19: 47 behind in orchestkit (45 false unmerged commits, 0 against
 * origin) and 587 behind in hq-ext-plugin (731 false).
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync, appendFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import {
  resolveBase,
  unmergedCommitCount,
} from '../../../pretool/bash/worktree-merge-verifier.js';

let stale: string; // has origin/main AHEAD of a stale local main
let noRemote: string; // local main only, no remote-tracking ref
let empty: string; // no commits, no refs at all

function run(args: string[], cwd: string): string {
  return execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
}

function initRepo(prefix: string): string {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  run(['init', '-q', '-b', 'main', '.'], dir);
  run(['config', 'user.email', 't@t.t'], dir);
  run(['config', 'user.name', 't'], dir);
  return dir;
}

beforeAll(() => {
  // --- the bug's shape: local main stale, origin/main current ---
  stale = initRepo('ork-3569-stale-');
  writeFileSync(join(stale, 'f.txt'), 'base\n');
  run(['add', '.'], stale);
  run(['commit', '-qm', 'base'], stale);
  const baseSha = run(['rev-parse', 'HEAD'], stale).trim();

  // A branch that genuinely lands in main.
  run(['checkout', '-qb', 'landed'], stale);
  appendFileSync(join(stale, 'f.txt'), 'landed\n');
  run(['commit', '-qam', 'landed'], stale);

  // main absorbs it, and the remote-tracking ref records that.
  run(['checkout', '-q', 'main'], stale);
  run(['merge', '-q', '--ff-only', 'landed'], stale);
  run(['update-ref', 'refs/remotes/origin/main', 'main'], stale);

  // ...then the LOCAL main rots back to base, which is what actually happens
  // when you never check main out and only ever fetch.
  run(['reset', '-q', '--hard', baseSha], stale);

  noRemote = initRepo('ork-3569-noremote-');
  writeFileSync(join(noRemote, 'f.txt'), 'base\n');
  run(['add', '.'], noRemote);
  run(['commit', '-qm', 'base'], noRemote);

  empty = initRepo('ork-3569-empty-');
});

afterAll(() => {
  for (const d of [stale, noRemote, empty]) {
    if (d) rmSync(d, { recursive: true, force: true });
  }
});

describe('#3569 resolveBase prefers origin/<base>', () => {
  it('returns origin/main when the remote-tracking ref exists', () => {
    expect(resolveBase(stale)).toBe('origin/main');
  });

  it('falls back to the local ref when there is no remote-tracking ref', () => {
    expect(resolveBase(noRemote)).toBe('main');
  });

  it('returns null when no base ref resolves, rather than guessing "main"', () => {
    // "could not measure" must stay distinguishable from "measured zero".
    expect(resolveBase(empty)).toBeNull();
  });
});

describe('#3569 the false-positive this prevents', () => {
  it('a stale LOCAL main reports the merged branch as unmerged', () => {
    // This is the bug: same branch, wrong ref, non-zero answer.
    expect(unmergedCommitCount(stale, 'landed', 'main')).toBeGreaterThan(0);
  });

  it('origin/main reports it correctly as fully merged', () => {
    expect(unmergedCommitCount(stale, 'landed', 'origin/main')).toBe(0);
  });

  it('resolveBase picks the ref that gives the TRUE answer', () => {
    const base = resolveBase(stale);
    expect(base).not.toBeNull();
    expect(unmergedCommitCount(stale, 'landed', base as string)).toBe(0);
  });
});
